// Функция для генерации SVG элементов на основе возраста и энергии
export function generateAgePositionsSVG(chakras) {
    const svgContainer = document.querySelector("#matrixResult svg");

    if (!svgContainer) {
        console.error("❌ Ошибка: контейнер SVG не найден!");
        return;
    }
    console.log("✅ SVG контейнер найден");

    agePositions.forEach(pos => {
        const [minAge] = pos.range.split('-').map(Number);
        const energyFormula = getEnergyForAgeLabel(pos.range, chakras);
        console.log(`🎯 Возраст ${minAge}, энергия:`, energyFormula);

        if (!energyFormula) {
            console.warn(`⚠️ Нет энергии для возраста ${minAge}`);
            return;
        }

        // Добавляем текст энергии в SVG
        const text = document.createElementNS("http://www.w3.org/2000/svg", "text");
        text.setAttribute("x", pos.cx);
        text.setAttribute("y", pos.cy);
        text.setAttribute("text-anchor", "middle");
        text.setAttribute("font-size", pos.fontSize);
        text.setAttribute("fill", pos.textColor);
        text.textContent = energyFormula;
        svgContainer.appendChild(text);
    });
}

document.addEventListener("DOMContentLoaded", () => {
    const calculateMatrix = () => {
        const dob = document.getElementById('year').value;

        if (!dob) {
            alert('Пожалуйста, введите дату рождения.');
            return;
        }

        const [year, month, day] = dob.split('-').map(Number);
        const chakras = calculateChakras(day, month, year);

        generateAgePositionsSVG(chakras);
    };

    document.querySelector('.btn').addEventListener('click', calculateMatrix);
});
  